// Some portions generated by Claude

// Plan task M14.2 (user request): SPARQL Update, Add, Remove and Clear stay on their page. While the server works
// the button is disabled and a spinner says what is happening; when it is done a green tick says so. Summary is
// never shown.
// @ts-check
const { test, expect } = require('@playwright/test');
const {
	createSeededRepository,
	deleteRepository,
	repositoryPageUrl,
	serverBaseUrl,
	uniqueRepositoryId,
	waitForRoute
} = require('./workbench-test-helpers.js');

const REPOSITORY_ID = uniqueRepositoryId('workbench-write-in-place');
const SPL = 'http://example.org/graph/spl';

test.beforeAll(async ({ request }) => {
	await createSeededRepository(request, serverBaseUrl(), REPOSITORY_ID, { graphs: ['spl'] });
});

test.afterAll(async ({ request }) => {
	await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

test.beforeEach(async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
});

async function sizeOf(request, context) {
	const query = context ? `?context=${encodeURIComponent(`<${context}>`)}` : '';
	const response = await request.get(`${serverBaseUrl()}/repositories/${encodeURIComponent(REPOSITORY_ID)}/size${query}`);
	return Number((await response.text()).trim());
}

async function insert(request, statements) {
	const response = await request.post(`${serverBaseUrl()}/repositories/${encodeURIComponent(REPOSITORY_ID)}/statements`,
		{ form: { update: `INSERT DATA { ${statements} }` } });
	expect(response.ok()).toBe(true);
}

/** Hold the page's POSTs to view until release() is called; Summary requests are recorded. */
async function holdPosts(page, view) {
	let release;
	const gate = new Promise((resolve) => { release = resolve; });
	const summaries = [];
	page.on('request', (request) => {
		if (new URL(request.url()).pathname.endsWith('/summary')) {
			summaries.push(request.url());
		}
	});
	await page.route((url) => url.pathname.endsWith('/' + view), async (route) => {
		if (route.request().method() === 'POST') {
			await gate;
		}
		await route.continue();
	});
	return { release: () => release(), summaries };
}

async function expectWorking(page, form, label) {
	const status = page.locator(`${form} .workbench-submit-status`);
	await expect(status).toHaveAttribute('data-state', 'running');
	await expect(status).toHaveText(label);
	await expect(status.locator('.workbench-submit-status__spinner')).toBeVisible();
	await expect(page.locator(form)).toHaveAttribute('aria-busy', 'true');
	await expect(page.locator(`${form} [type="submit"]`)).toBeDisabled();
}

async function expectDone(page, form, label, view) {
	const status = page.locator(`${form} .workbench-submit-status`);
	await expect(status).toHaveAttribute('data-state', 'done');
	await expect(status).toHaveText(label);
	await expect(status).toHaveAttribute('role', 'status');
	const tick = status.locator('[data-workbench-icon="check"]');
	await expect(tick).toBeVisible();
	const colors = await tick.evaluate((icon) => {
		const probe = document.createElement('span');
		probe.style.color = 'var(--workbench-success)';
		document.body.appendChild(probe);
		const success = getComputedStyle(probe).color;
		probe.remove();
		return { tick: getComputedStyle(icon).color, success };
	});
	expect(colors.tick, 'the tick is green').toBe(colors.success);
	await expect(page.locator(form)).toHaveAttribute('aria-busy', 'false');
	await expect(page).toHaveURL(new RegExp(`/repositories/${REPOSITORY_ID}/${view}$`));
	await expect(page.locator('#workbench-outlet')).toHaveAttribute('data-workbench-route', view);
}

test('SPARQL Update shows a spinner while it runs and a tick when it is done, on its own page', async ({ page, request }) => {
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'update'));
	await waitForRoute(page, 'update');
	const before = await sizeOf(request);
	const held = await holdPosts(page, 'update');
	await page.locator('#update-editor .CodeMirror').evaluate((element) =>
		element.CodeMirror.setValue('INSERT DATA { <urn:in-place:update> <urn:in-place:p> "u" }'));

	await page.locator('#update-form [type="submit"]').click();
	await expectWorking(page, '#update-form', 'Executing update…');
	held.release();

	await expectDone(page, '#update-form', 'Update executed', 'update');
	expect(await sizeOf(request)).toBe(before + 1);
	expect(held.summaries, 'Summary is not shown').toEqual([]);
	expect(await page.locator('#update-editor .CodeMirror').evaluate((element) => element.CodeMirror.getValue()))
		.toContain('urn:in-place:update');

	// Editing the update clears the tick: it belongs to the update that ran.
	await page.locator('#update-editor .CodeMirror').click();
	await page.keyboard.type(' ');
	await expect(page.locator('#update-form .workbench-submit-status')).toHaveAttribute('data-state', 'idle');
	await expect(page.locator('#update-form .workbench-submit-status')).toHaveText('');
});

test('Add RDF shows a spinner while it adds and a tick when it is done, on its own page', async ({ page, request }) => {
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'add'));
	await waitForRoute(page, 'add');
	const before = await sizeOf(request);
	const held = await holdPosts(page, 'add');
	await page.locator('label[for="source-text"]').click();
	await page.locator('#text').fill('<urn:in-place:add> <urn:in-place:p> "a" .\n');

	await page.locator('#add-form [type="submit"]').click();
	await expectWorking(page, '#add-form', 'Adding data…');
	held.release();

	await expectDone(page, '#add-form', 'Data added', 'add');
	expect(await sizeOf(request)).toBe(before + 1);
	expect(held.summaries).toEqual([]);
	await expect(page.locator('#text')).toHaveValue('<urn:in-place:add> <urn:in-place:p> "a" .\n');
});

test('Remove shows a spinner while it removes, then a tick with the number removed and the new count', async ({ page, request }) => {
	await insert(request, '<urn:in-place:remove> <urn:in-place:p> "one", "two" .');
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'remove'));
	await waitForRoute(page, 'remove');
	const held = await holdPosts(page, 'remove');
	await page.locator('#subj').fill('<urn:in-place:remove>');
	await expect(page.locator('#remove-count')).toHaveText('2 statements match');

	await page.locator('#remove-form [type="submit"]').click();
	await page.getByRole('dialog').getByRole('button', { name: 'Remove statements' }).click();
	await expectWorking(page, '#remove-form', 'Removing statements…');
	held.release();

	await expectDone(page, '#remove-form', 'Removed 2 statements', 'remove');
	await expect(page.locator('#remove-count')).toHaveText('No statements match');
	await expect(page.locator('#subj')).toHaveValue('<urn:in-place:remove>');
	expect(held.summaries).toEqual([]);
});

test('Clear shows a spinner while it clears, then a tick and the graphs that are left', async ({ page, request }) => {
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'clear'));
	await waitForRoute(page, 'clear');
	const held = await holdPosts(page, 'clear');
	const graph = page.locator('#clear-form select[name="context"]');
	await expect(graph.locator(`option[value="<${SPL}>"]`)).toHaveCount(1);
	await graph.selectOption(`<${SPL}>`);

	await page.locator('#clear-form [type="submit"]').click();
	await page.getByRole('dialog', { name: 'Clear graph?' }).getByRole('button', { name: 'Clear graph' }).click();
	await expectWorking(page, '#clear-form', 'Clearing…');
	held.release();

	await expectDone(page, '#clear-form', 'Graph cleared', 'clear');
	await expect(graph.locator(`option[value="<${SPL}>"]`), 'the cleared graph is gone from the list').toHaveCount(0);
	await expect(graph.locator('option').first()).not.toContainText('Counting…');
	expect(await sizeOf(request, SPL)).toBe(0);
	expect(held.summaries).toEqual([]);
});

test('a write whose request fails says so on its page and can be sent again', async ({ page }) => {
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'update'));
	await waitForRoute(page, 'update');
	await page.route((url) => url.pathname.endsWith('/update'), (route) => (route.request().method() === 'POST'
		? route.abort('failed') : route.continue()));
	await page.locator('#update-editor .CodeMirror').evaluate((element) =>
		element.CodeMirror.setValue('INSERT DATA { <urn:in-place:failed> <urn:in-place:p> "f" }'));

	await page.locator('#update-form [type="submit"]').click();

	const status = page.locator('#update-form .workbench-submit-status');
	await expect(status).toHaveAttribute('data-state', 'failed');
	await expect(status).toHaveText('No answer from the server; check the repository before trying again.');
	await expect(status.locator('[data-workbench-icon="error"]')).toBeVisible();
	await expect(page.locator('#update-form [type="submit"]')).toBeEnabled();
	await expect(page).toHaveURL(/\/update$/);
});
